// MYTHRIL TIDE - assets/fonts.js : era fonts baked as base64 data URIs (offline, file://-safe).
// OFL-licensed: Spectral (Production Type) body+italic, Cinzel (Natanael Gama) display. See assets/fonts/OFL-*.txt
(function(){
  if (typeof document === 'undefined' || !document.fonts || !window.FontFace) return;
  var F = [
    {fam:'Spectral', style:'normal', weight:'normal', d:'data:font/ttf;base64,'},
    {fam:'Spectral', style:'italic', weight:'normal', d:'data:font/ttf;base64,'},
    {fam:'Cinzel', style:'normal', weight:'700', d:'data:font/ttf;base64,'},
  ];
  window.FONTS_READY = Promise.all(F.map(function(f){
    try { var ff = new FontFace(f.fam, 'url('+f.d+')', {style:f.style, weight:f.weight});
      return ff.load().then(function(l){ document.fonts.add(l); return l; }).catch(function(){}); }
    catch(e){ return null; }
  })).then(function(){ window.FONTS_LOADED = true; });
})();
